<script setup lang="tsx">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
// Monaco Editor 改为动态加载
import { loadMonacoWithLanguage, loadMonacoLanguage } from "@/util/monaco";
import type { editor } from "monaco-editor";
import { useCurrentInstance } from "@/util";

// monaco 实例将在动态加载后赋值
let monaco: typeof import("monaco-editor/esm/vs/editor/editor.api") | null = null;
import { GetCommonErrorCode, ShowErrorTips } from "@/util/tips";
import {
  GetJudgeJob,
  GetJudgeStatusStr,
  GetJudgeStatusTheme,
  GetJudgeStatusTips,
  IsJudgeStatusRunning,
  JudgeStatus,
  ParseJudgeJob,
  PostJudgeJobPrivate,
  PostRejudgeJob,
} from "@/apis/judge.ts";
import { GetJudgeLanguageStr, GetHighlightKeyByJudgeLanguage } from "@/apis/language.ts";
import type { JudgeJob, JudgeJobView, JudgeTaskView } from "@/types/judge.ts";
import type { ButtonProps } from "tdesign-vue-next";
import type { BaseTableCol, TableRowData } from "tdesign-vue-next";
import type { CellParams } from "@/types/table";
import { AuthType } from "@/auth";
import { useUserStore } from "@/stores/user.ts";
import { useBreakpoint } from "@/composables/useBreakpoint";
import { GetContestProblemIndexStr } from "@/apis/contest.ts";
import { handleGotoContestProblem } from "@/util/router.ts";
import { GetAvatarUrl } from "@/util/avatar.ts";

const route = useRoute();
const router = useRouter();
const userStore = useUserStore();
const { globalProperties } = useCurrentInstance();
const { isMobile } = useBreakpoint();

let viewActive = false;
let refreshTimeout: ReturnType<typeof setTimeout>;
let judgeId = 0;
let contestId = 0;
const judgerName = ref("");
const judgeJob = ref<JudgeJobView | null>(null);
const jobProgress = ref(0);
const jobProgressStatus = ref(null as null | string);
const jobProgressToColor = ref({
  from: "#5a96ff",
  to: "#00A870",
});
const codeContainerRef = ref<HTMLElement | null>(null);
let codeEditor: editor.IStandaloneCodeEditor | null = null;
let decorationIds: string[] = [];

const ListColumns = ref<BaseTableCol<TableRowData>[]>([
  {
    title: "ID",
    colKey: "id",
  },
  {
    title: "问题",
    colKey: "problemKey",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      if (contestId) {
        return (
          <t-button variant="text" onClick={() => handleGotoContestProblem(contestId, data.row.contestProblemIndex)}>
            {GetContestProblemIndexStr(data.row.contestProblemIndex)}
          </t-button>
        );
      }
      return (
        <t-button variant="text" onClick={() => handleGotoProblem(data.row.problemKey)}>
          {data.row.problemKey}
        </t-button>
      );
    },
  },
  {
    title: "状态",
    colKey: "status",
    align: "center",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      const status = data.row.status as JudgeStatus;
      const statusStr = GetJudgeStatusStr(status);
      const theme = GetJudgeStatusTheme(status);
      const finalElements = [];
      if (IsJudgeStatusRunning(status)) {
        finalElements.push(<t-loading text={data.row.state} size="small" class="dida-status-loading"></t-loading>);
      }
      finalElements.push(<span>{statusStr}</span>);
      return (
        <t-button theme={theme} variant="outline">
          {finalElements}
        </t-button>
      );
    },
  },
  {
    title: "分数",
    colKey: "score",
  },
  {
    title: "时间",
    colKey: "time",
  },
  {
    title: "内存",
    colKey: "memory",
  },
  {
    title: "代码",
    colKey: "language",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      return <span>{GetJudgeLanguageStr(data.row.language) + " / " + data.row.codeLength}</span>;
    },
  },
  {
    title: "作者",
    colKey: "inserter",
    width: 200,
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      const avatarUrl = GetAvatarUrl(data.row.inserterUsername, data.row.inserterEmail);
      return (
        <t-space>
          <t-avatar shape="round" size="32px" image={avatarUrl} hide-on-load-failed={false} />
          <t-button variant="text" onClick={() => handleGotoUser(data.row.inserterUsername)}>
            {data.row.inserterNickname}
          </t-button>
        </t-space>
      );
    },
  },
  {
    title: "提交时间",
    colKey: "insertTime",
    width: 180,
  },
]);

const dataLoading = ref(false);
const isRejudging = ref(false);
const isPrivate = ref(false);
const isPrivateLoading = ref(false);

const judgeJobViews = ref<JudgeJobView[]>();

const hasEditAuth = computed(() => {
  return userStore.hasAuth(AuthType.ManageJudge);
});

const hasEditPrivateAuth = computed(() => {
  return userStore.hasAuth(AuthType.ManageJudge) || (judgeJob.value && userStore.getUserId == judgeJob.value.inserter);
});

const handleClickRejudge = async () => {
  if (isRejudging.value) {
    return;
  }
  isRejudging.value = true;
  try {
    const res = await PostRejudgeJob(judgeId);
    if (res.code === 0) {
      await fetchData(true);
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowErrorTips(globalProperties, GetCommonErrorCode());
  } finally {
    isRejudging.value = false;
  }
};

const handleGotoProblem = (id: string) => {
  if (!id) {
    return;
  }
  router.push({ path: "/problem/" + id });
};

const handleGotoUser = (user: string) => {
  if (!user) {
    return;
  }
  router.push({ path: "/user/" + user });
};

interface HintDiffItem {
  lineNumber: number;
  expected: string;
  actual: string;
  isDiff: boolean;
  isNotFound: boolean;
  isExtraOutput: boolean;
}

const parseHintDiff = (hint: string): HintDiffItem[] => {
  if (!hint) return [];
  const results: HintDiffItem[] = [];
  
  const diffRegex = /#(\d+)\s+(\S+)\s*!=\s*(\S+)/g;
  let match;
  while ((match = diffRegex.exec(hint)) !== null) {
    results.push({
      lineNumber: parseInt(match[1], 10),
      expected: match[2],
      actual: match[3],
      isDiff: true,
      isNotFound: false,
      isExtraOutput: false,
    });
  }
  
  const notFoundRegex = /#(\d+)\s+not\s+found\s+(\S+)/gi;
  while ((match = notFoundRegex.exec(hint)) !== null) {
    results.push({
      lineNumber: parseInt(match[1], 10),
      expected: match[2],
      actual: "",
      isDiff: true,
      isNotFound: true,
      isExtraOutput: false,
    });
  }
  
  const extraOutputRegex = /#(\d+)\s+extra\s+output\s+(\S+)/gi;
  while ((match = extraOutputRegex.exec(hint)) !== null) {
    results.push({
      lineNumber: parseInt(match[1], 10),
      expected: "",
      actual: match[2],
      isDiff: true,
      isNotFound: false,
      isExtraOutput: true,
    });
  }
  
  return results.sort((a, b) => a.lineNumber - b.lineNumber);
};

const taskRender = (task: JudgeTaskView) => {
  const status = task.status as JudgeStatus;
  const statusStr = GetJudgeStatusStr(status);
  let theme: ButtonProps["theme"];
  switch (status) {
    case JudgeStatus.Init:
    case JudgeStatus.Rejudge:
    case JudgeStatus.Compiling:
    case JudgeStatus.Running:
      theme = "default";
      break;
    case JudgeStatus.Accept:
      theme = "success";
      break;
    case JudgeStatus.PE:
      theme = "warning";
      break;
    default:
      theme = "danger";
      break;
  }
  return (
    <t-space>
      <t-button theme="default" variant="outline">
        {task.taskId}
      </t-button>
      <t-button theme={theme} variant="outline">
        {statusStr}
      </t-button>
      <span>分数：{task.score}</span>
      <span>用时：{task.time}</span>
      <span>内存：{task.memory}</span>
    </t-space>
  );
};

const handlePrivateChanged = async (value: boolean) => {
  isPrivateLoading.value = true;
  try {
    const res = await PostJudgeJobPrivate(judgeId, value);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    isPrivate.value = value;
  } catch (err) {
    console.error(err);
    ShowErrorTips(globalProperties, GetCommonErrorCode());
  } finally {
    isPrivateLoading.value = false;
  }
};

// 监听模板题不可编辑区域变化，刷新 Monaco 装饰。
// 防御性处理：immutableRegions 可能在 judgeJob 赋值后才到达 view 层。
watch(
  () => judgeJob.value?.immutableRegions,
  () => {
    nextTick(() => updateImmutableDecorations());
  },
);

// 根据 judgeJob.immutableRegions 给 Monaco editor 加整行灰底装饰。
// immutable_regions 是合并后 code 字符串的 Go UTF-8 字节偏移 [start, end) 半开区间。
// Monaco / JS 用 UTF-16 code unit 偏移，中文等非 ASCII 字符会错位，需要做转换。
// 用户编辑区保持 monaco 默认高亮不变，仅模板区做视觉区分。
const buildByteToCharMap = (code: string): number[] => {
  const encoder = new TextEncoder();
  const bytes = encoder.encode(code);
  const b2c = new Array(bytes.length + 1);
  let ci = 0;
  for (let bi = 0; bi <= bytes.length; bi++) {
    b2c[bi] = ci;
    if (bi < bytes.length && (bytes[bi] & 0xc0) !== 0x80) ci++;
  }
  return b2c;
};

const updateImmutableDecorations = () => {
  if (!codeEditor) return;
  const model = codeEditor.getModel();
  if (!model) return;

  const regions = judgeJob.value?.immutableRegions;
  if (!regions || regions.length === 0) {
    if (decorationIds.length > 0) {
      decorationIds = model.deltaDecorations(decorationIds, []);
    }
    return;
  }

  const code = model.getValue();
  const b2c = buildByteToCharMap(code);
  const totalBytes = b2c.length - 1; // TextEncoder 输出长度即 Go len()

  // monaco 为动态加载后赋值的实例，判空后再使用；用局部常量固定引用，避免闭包内被判定为可能为 null
  if (!monaco) return;
  const monacoApi = monaco;

  // 类型来自 monaco-editor 的命名空间导入（`monaco` 是变量，不能作为类型命名空间使用）
  const decs: editor.IModelDeltaDecoration[] = [];
  for (const region of regions) {
    if (region.end <= region.start) continue;
    const charStart = b2c[Math.min(region.start, totalBytes)];
    const charEnd = b2c[Math.min(region.end, totalBytes)];
    if (charEnd <= charStart) continue;

    const startPos = model.getPositionAt(charStart);
    const endPos = model.getPositionAt(charEnd);
    // 半开区间：如果 end 落在某行 col=1，则该行不在范围内
    let lastLine = endPos.lineNumber;
    if (endPos.column === 1 && lastLine > startPos.lineNumber) {
      lastLine = lastLine - 1;
    }
    for (let ln = startPos.lineNumber; ln <= lastLine; ln++) {
      decs.push({
        range: new monacoApi.Range(ln, 1, ln, 1),
        options: {
          isWholeLine: true,
          className: "dida-immutable-line",
        },
      });
    }
  }
  decorationIds = model.deltaDecorations(decorationIds, decs);
};

const setCodeToEditor = async (code: string, language: string) => {
  if (!codeContainerRef.value) return;

  // 首次创建时动态加载 monaco 核心和对应语言
  if (!codeEditor) {
    monaco = await loadMonacoWithLanguage(language);
    codeEditor = monaco.editor.create(codeContainerRef.value, {
      value: code,
      language,
      readOnly: true,
      theme: "vs",
      minimap: { enabled: false },
      automaticLayout: true,
      scrollBeyondLastLine: false,
      fontSize: 14,
      lineNumbers: "on",
      wordWrap: "on",
      folding: true,
    });
  } else {
    const model = codeEditor.getModel();
    if (model) {
      // 动态加载语言（如果尚未加载）
      await loadMonacoLanguage(language);
      model.setValue(code);
      monaco?.editor.setModelLanguage(model, language);
    }
  }
  updateImmutableDecorations();
};

const disposeCodeEditor = () => {
  if (codeEditor) {
    decorationIds = [];
    codeEditor.dispose();
    codeEditor = null;
  }
};

const fetchData = async (needLoading: boolean) => {
  if (needLoading) {
    dataLoading.value = true;
  }
  let needRefresh = false;
  try {
    const res = await GetJudgeJob(judgeId, contestId);
    judgeJobViews.value = [];
    if (res.code === 0) {
      const response = res.data as JudgeJob;
      const result = ParseJudgeJob(response);
      judgeJobViews.value?.push(result);

      judgerName.value = result.judgerName;

      jobProgressToColor.value.to = "#00A870";

      if (IsJudgeStatusRunning(response.status)) {
        jobProgressStatus.value = "active";
        if (result.taskTotal > 0) {
          jobProgress.value = Number(((result.taskCurrent / result.taskTotal) * 100).toFixed(2));
          if (result.taskCurrent >= result.taskTotal) {
            jobProgress.value = 99;
          }
        } else {
          jobProgress.value = 0;
        }
      } else {
        jobProgress.value = 100;
        if (response.status === JudgeStatus.Accept) {
          jobProgressStatus.value = "success";
        } else if (response.status === JudgeStatus.PE) {
          jobProgressToColor.value.to = "#F57C20";
          jobProgressStatus.value = "warning";
        } else {
          jobProgressToColor.value.to = "#F56C6C";
          jobProgressStatus.value = "error";
        }
      }

      if (response.code) {
        const language = GetHighlightKeyByJudgeLanguage(response.language);
        await nextTick();
        await setCodeToEditor(response.code, language);
      }

      judgeJob.value = result;

      isPrivate.value = judgeJob.value.private;

      if (IsJudgeStatusRunning(response.status)) {
        needRefresh = true;
      }
    } else {
      if (needLoading) {
        ShowErrorTips(globalProperties, res.code);
      }
      if (contestId) {
        await router.push({ name: "contest-judge", params: { contestId } });
      } else {
        await router.push({ name: "judge-list" });
      }
    }
  } catch (err) {
    console.error(err);
    if (needLoading) {
      ShowErrorTips(globalProperties, GetCommonErrorCode());
    }
  } finally {
    if (needLoading) {
      dataLoading.value = false;
    }
    if (needRefresh && viewActive) {
      refreshTimeout = setTimeout(() => {
        fetchData(false);
      }, 5000);
    }
  }
};

// 初始化分页信息
onMounted(async () => {
  viewActive = true;

  if (Array.isArray(route.params.judgeId)) {
    judgeId = Number(route.params.judgeId[0]);
  } else {
    judgeId = Number(route.params.judgeId);
  }

  if (Array.isArray(route.params.contestId)) {
    contestId = Number(route.params.contestId[0]);
  } else {
    contestId = Number(route.params.contestId);
  }

  if (!judgeId) {
    await router.push({ name: "judge" });
    return;
  }

  await fetchData(true);
});

onBeforeUnmount(() => {
  viewActive = false;
  clearTimeout(refreshTimeout);
  disposeCodeEditor();
});
</script>

<template>
  <t-progress :color="jobProgressToColor" :status="jobProgressStatus" class="dida-job-progress" :percentage="jobProgress" />

  <t-card style="margin: 10px">
    <div style="overflow-x: auto; width: 100%">
      <t-table :data="judgeJobViews" :columns="ListColumns" row-key="id" vertical-align="top" :hover="true" :loading="dataLoading" />
    </div>
  </t-card>

  <t-row>
    <t-col :span="isMobile ? 12 : 8">
      <t-alert
        v-if="judgeJob?.immutableRegions && judgeJob.immutableRegions.length > 0"
        theme="info"
        title="本题为模板题"
        :closable="false"
        style="margin: 10px"
      >
        下方代码中共有 {{ judgeJob.immutableRegions.length }} 段不可编辑（模板）区，
        其余为本次提交中您撰写的代码。
      </t-alert>
      <div class="dida-code-container">
        <div ref="codeContainerRef" class="dida-code-monaco"></div>
      </div>
    </t-col>
    <t-col :span="isMobile ? 12 : 4">
      <div style="margin: 20px">
        <t-descriptions layout="vertical" :bordered="true">
          <t-descriptions-item label="判题机">{{ judgerName }}</t-descriptions-item>
          <t-descriptions-item label="判题时间">{{ judgeJob?.judgeTime }}</t-descriptions-item>
        </t-descriptions>
        <t-card v-if="hasEditPrivateAuth" style="margin: 10px 0">
          <t-form layout="inline">
            <t-form-item label="是否隐藏代码">
              <t-switch v-model="isPrivate" :loading="dataLoading || isPrivateLoading" @change="handlePrivateChanged"></t-switch>
            </t-form-item>
          </t-form>
        </t-card>
        <t-card class="dida-card-tips">
          {{ dataLoading ? "数据正在加载，请等待" : GetJudgeStatusTips(judgeJob?.status) }}
        </t-card>
        <t-card class="dida-card-tips">
            <p>在判题时，如果在得到完整用户输出之前就产生了报错会提示对应状态。</p>
            <p>然后对于普通评测，会将所有输出以空白字符分割为若干块，然后逐个块对比期望输出与用户输出。</p>
            <p>若发现不匹配字段，判定为答案错误，在可能时提示差异块的编号和信息</p>
            <p>若所有块都能匹配，则根据题目定义的空白字符处理方式来判断</p>
            <p>如果按照空白字符忽略的内容一致，判定为正确，否则判定为格式错误</p>
        </t-card>
      </div>
    </t-col>
  </t-row>

  <t-card v-if="judgeJob?.compileMessage" class="compile-message">{{ judgeJob?.compileMessage }}</t-card>

  <t-collapse v-if="judgeJob?.task && judgeJob?.task.length > 0" class="task-panel">
    <t-collapse-panel v-for="task in judgeJob?.task" :key="task.taskId" :header="() => taskRender(task)">
      <t-card>
        {{ GetJudgeStatusTips(task.status) }}
      </t-card>
      <t-card v-if="task.content" class="dida-card-tips">
        <md-preview :model-value="task.content"></md-preview>
      </t-card>
      <t-card v-if="task.hint" class="dida-card-tips">
        <template v-if="parseHintDiff(task.hint).length > 0">
          <div class="hint-diff-container">
            <div v-for="(diff, index) in parseHintDiff(task.hint)" :key="index" class="hint-diff-row">
              <span class="hint-line-number">块 {{ diff.lineNumber }}</span>
              <div class="hint-diff-values">
                <template v-if="diff.isExtraOutput">
                  <div class="hint-diff-extra">
                    <span class="hint-label">期望输出:</span>
                    <span class="hint-value hint-empty">(无)</span>
                  </div>
                  <div class="hint-diff-actual">
                    <span class="hint-label">实际输出:</span>
                    <span class="hint-value">{{ diff.actual }}</span>
                  </div>
                </template>
                <template v-else-if="diff.isNotFound">
                  <div class="hint-diff-expected">
                    <span class="hint-label">期望输出:</span>
                    <span class="hint-value">{{ diff.expected }}</span>
                  </div>
                  <div class="hint-diff-missing">
                    <span class="hint-label">实际输出:</span>
                    <span class="hint-value hint-empty">(缺失)</span>
                  </div>
                </template>
                <template v-else>
                  <div class="hint-diff-expected">
                    <span class="hint-label">期望输出:</span>
                    <span class="hint-value">{{ diff.expected }}</span>
                  </div>
                  <div class="hint-diff-actual">
                    <span class="hint-label">实际输出:</span>
                    <span class="hint-value">{{ diff.actual }}</span>
                  </div>
                </template>
              </div>
            </div>
          </div>
        </template>
        <template v-else>
          <md-preview :model-value="task.hint"></md-preview>
        </template>
      </t-card>
    </t-collapse-panel>
  </t-collapse>
  <div v-if="hasEditAuth" class="dida-edit-container">
    <t-button :loading="isRejudging" @click="handleClickRejudge">重新评测</t-button>
  </div>
</template>

